//
// Basic auth.
//

static const char B64[] =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

// Base64 of "user:password", written by hand so the whole check stays one
// comparison against the client header.
static void base64_encode(const char *in, char *out, size_t cap)
{
    size_t o = 0;
    size_t len = strlen(in);
    for (size_t i = 0; i < len && o + 4 < cap; i += 3) {
        uint32_t v = (uint8_t)in[i] << 16;
        if (i + 1 < len) v |= (uint8_t)in[i + 1] << 8;
        if (i + 2 < len) v |= (uint8_t)in[i + 2];
        out[o++] = B64[(v >> 18) & 0x3F];
        out[o++] = B64[(v >> 12) & 0x3F];
        out[o++] = (i + 1 < len) ? B64[(v >> 6) & 0x3F] : '=';
        out[o++] = (i + 2 < len) ? B64[v & 0x3F] : '=';
    }
    out[o] = '\0';
}

static void build_expected_auth(void)
{
    expected_auth[0] = '\0';
    // sanitize() keeps the setup password non-empty, so this is only a guard
    // against a hand-edited value reaching the server.
    if (settings.web_password[0] == '\0') return;
    char raw[100];
    char encoded[140];
    snprintf(raw, sizeof(raw), "%s:%s", settings.web_user, settings.web_password);
    base64_encode(raw, encoded, sizeof(encoded));
    snprintf(expected_auth, sizeof(expected_auth), "Basic %s", encoded);
}

static bool auth_ok(httpd_req_t *req)
{
    if (expected_auth[0] == '\0') return true;
    char got[176];
    if (httpd_req_get_hdr_value_len(req, "Authorization") == 0) return false;
    if (httpd_req_get_hdr_value_str(req, "Authorization", got, sizeof(got)) != ESP_OK) {
        return false;
    }
    return strcmp(got, expected_auth) == 0;
}

static esp_err_t deny(httpd_req_t *req)
{
    httpd_resp_set_hdr(req, "WWW-Authenticate", "Basic realm=\"moonstation\"");
    return httpd_resp_send_err(req, HTTPD_401_UNAUTHORIZED, "login required");
}

//
// The settings table the page may read and write. Everything outside of it
// stays a compile time value, see the comment on settings_t.
//

typedef enum { F_STR, F_U8, F_U16, F_U32, F_I8, F_I16 } field_type_t;

typedef struct {
    const char *key;
    field_type_t type;
    size_t offset;
    size_t size; // string capacity, unused for numbers
    int32_t lo;  // clamp range for numbers
    int32_t hi;
    bool secret; // never sent back to the browser, see config_get()
} field_t;

#define FIELD(f, t, s, lo, hi) {#f, t, offsetof(settings_t, f), s, lo, hi, false}
// A secret can only be written. The page gets "stored" or "not set" instead
// of the value, an empty field on save keeps what is stored, and the extra
// "<key>.clear" flag erases it.
#define SECRET_FIELD(f, s) {#f, F_STR, offsetof(settings_t, f), s, 0, 0, true}

